drop policy if exists quote_settings_manager_write on public.quote_settings;
create policy quote_settings_manager_insert on public.quote_settings for insert to authenticated with check (private.has_org_role(org_id,array['owner','admin','manager']));
create policy quote_settings_manager_update on public.quote_settings for update to authenticated using (private.has_org_role(org_id,array['owner','admin','manager'])) with check (private.has_org_role(org_id,array['owner','admin','manager']));
create policy quote_settings_manager_delete on public.quote_settings for delete to authenticated using (private.has_org_role(org_id,array['owner','admin','manager']));
drop policy if exists quote_discount_services_manager_write on public.quote_discount_services;
create policy quote_discount_services_manager_insert on public.quote_discount_services for insert to authenticated with check (private.has_org_role(org_id,array['owner','admin','manager']));
create policy quote_discount_services_manager_update on public.quote_discount_services for update to authenticated using (private.has_org_role(org_id,array['owner','admin','manager'])) with check (private.has_org_role(org_id,array['owner','admin','manager']));
create policy quote_discount_services_manager_delete on public.quote_discount_services for delete to authenticated using (private.has_org_role(org_id,array['owner','admin','manager']));
drop policy if exists quote_items_staff_write_pending on public.quote_items;
create policy quote_items_staff_insert_pending on public.quote_items for insert to authenticated with check (private.has_org_role(org_id,array['owner','admin','manager','receptionist']) and exists(select 1 from public.quotes q where q.id=quote_items.quote_id and q.org_id=quote_items.org_id and q.status in ('draft','pending')));
create policy quote_items_staff_update_pending on public.quote_items for update to authenticated using (private.has_org_role(org_id,array['owner','admin','manager','receptionist']) and exists(select 1 from public.quotes q where q.id=quote_items.quote_id and q.org_id=quote_items.org_id and q.status in ('draft','pending'))) with check (private.has_org_role(org_id,array['owner','admin','manager','receptionist']) and exists(select 1 from public.quotes q where q.id=quote_items.quote_id and q.org_id=quote_items.org_id and q.status in ('draft','pending')));
create policy quote_items_staff_delete_pending on public.quote_items for delete to authenticated using (private.has_org_role(org_id,array['owner','admin','manager','receptionist']) and exists(select 1 from public.quotes q where q.id=quote_items.quote_id and q.org_id=quote_items.org_id and q.status in ('draft','pending')));
